function archive(ctx,view,detailYear=null){if(detailYear){const row=view.archive.find(x=>Number(x.year)===Number(detailYear));if(!row)return `${nav('archive')}<div class="empty">المؤتمر غير موجود.</div>`;const check=validateConferenceSnapshot(row.snapshot||{});return `${nav('archiveDetail')}<div class="conference-center"><article class="list-item"><div class="list-item-head"><div><h3>المؤتمر التنفيذي ${row.year}</h3><p>${ctx.esc(row.city)} · ${ctx.esc(row.packageName)} · أرشيف ثابت للعام نفسه.</p></div><span class="tag positive">مؤرشف</span></div><div class="conference-preview"><span>Replay · Snapshot ${ctx.esc(row.dataContractVersion||'—')}</span></div><div class="metric-row"><div><span>الحضور</span><b>${ctx.fmtNumber(row.snapshot?.social?.attendees||0)}</b></div><div><span>المشاهدات</span><b>${ctx.fmtNumber(row.snapshot?.social?.viewers||0)}</b></div><div><span>جودة البيانات</span><b>${ctx.esc(check.status)}</b></div></div><div class="action-row"><button class="primary-btn" ${actionAttr('conference-stage-replay')} data-year="${row.year}">إعادة عرض المؤتمر</button></div></article><article class="list-item"><h3>سجل تكلفة المؤتمر</h3>${row.payments.map(x=>`<p>${ctx.esc(x.vendor)} · ${ctx.fmtMoney(x.amount)} · ${ctx.esc(x.chequeId)}</p>`).join('')}</article></div>`;}return `${nav('archive')}<div class="conference-center">${view.archive.map(row=>`<article class="list-item"><div class="list-item-head"><div><h3>المؤتمر التنفيذي ${row.year}</h3><p>${ctx.esc(row.city)} · ${ctx.esc(row.packageName)} · ${ctx.esc(row.venue)}</p></div><span class="tag positive">مكتمل</span></div><div class="metric-row"><div><span>الحضور</span><b>${ctx.fmtNumber(row.snapshot?.social?.attendees||0)}</b></div><div><span>المشاهدات</span><b>${ctx.fmtNumber(row.snapshot?.social?.viewers||0)}</b></div><div><span>التكلفة</span><b>${ctx.fmtMoney(row.totalCost)}</b></div></div><div class="action-row"><button class="primary-btn" data-open="conference" data-arg="archive:${row.year}">فتح الأرشيف</button><button class="secondary-btn" ${actionAttr('conference-stage-replay')} data-year="${row.year}">إعادة العرض</button></div></article>`).join('')||'<div class="empty">لا توجد مؤتمرات مؤرشفة بعد.</div>'}</div>`;}
function render(ctx,arg){const parsed=parseArg(arg),view=snapshot(ctx.state);if(parsed.tab==='overview')return overview(ctx,view);if(parsed.tab==='monthly')return monthlyReport(ctx,view);if(parsed.tab==='people')return people(ctx,view);if(parsed.tab==='archive')return archive(ctx,view);if(parsed.tab==='archiveDetail')return archive(ctx,view,parsed.year);const current=rowForPresentation(ctx.state,view);return stageLauncher(ctx,current,parsed.slide);}
async function handleAction(btn,ctx){const id=btn.dataset.ghAction,s=ctx.state;if(id==='conference-prepare'){const conferenceView=snapshot(s);if(!conferenceView.pendingYear){globalThis.GH_WORKFLOW?.notify?.('لا يوجد عام مالي مكتمل بانتظار المؤتمر. يمكنك معاينة المحرك فقط حتى نهاية العام.','error',{state:s,panel:'conference'});return true;}const packageId=document.getElementById('conferencePackage')?.value||'global',year=Math.floor(Number(btn.dataset.year)||conferenceView.pendingYear),pack=PACKAGES[packageId]||PACKAGES.global,total=packageCost(packageId),ok=globalThis.GH_WORKFLOW?.confirm?globalThis.GH_WORKFLOW.confirm(`سيتم إصدار وصرف ${pack.items.length} شيكات فعلية من حساب القابضة بإجمالي ${ctx.fmtMoney(total)} لتجهيز مؤتمر ${year}. متابعة؟`,{state:s,panel:'conference',risk:'financial'}):window.confirm(`خصم ${ctx.fmtMoney(total)} عبر شيكات فعلية؟`);if(!ok)return true;try{await ctx.runAuthorizedDomainCommand('conference','prepare',{year,packageId},{idempotencyKey:`CONF-PREP-${year}`});ctx.pushAlert(`اكتمل تجهيز مؤتمر ${year}. صُرفت شيكات الموردين من الحساب الجاري للقابضة وسُجلت المستندات.`);ctx.updateKpis();ctx.openDrawer('conference','overview');}catch(error){globalThis.GH_WORKFLOW?.notify?.(`تعذر تجهيز المؤتمر: ${error.message}`,'error',{state:s,panel:'conference'});}return true;}
 if(id==='conference-start'){try{const out=(await ctx.runAuthorizedDomainCommand('conference','start',{}, {idempotencyKey:`${ensure(s).current?.id||'CONFERENCE'}-START`})).result,ui=ensure(s).ui||{},resume=ui.resume?.conferenceId===out.id&&ui.resume?.engine===getStageEngine()?.ENGINE_ID&&ui.resume?.planHash===out.presentation?.planHash?ui.resume:null,selected=document.getElementById('conferencePlaybackMode')?.value,mode=selected||resume?.mode||'full',scenes=globalThis.GH_CONF_MODEL.scenesForPlan(out.presentation.planBundle,mode),startScene=resume?Math.max(0,scenes.findIndex(scene=>scene.id===resume.sceneId)):0;launchStage(ctx,out,{live:true,startScene,mode});}catch(error){globalThis.GH_WORKFLOW?.notify?.(`تعذر بدء المؤتمر: ${error.message}`,'error',{state:s,panel:'conference'});}return true;}
 if(id==='conference-stage-preview'){try{const view=snapshot(s),current=rowForPresentation(s,view),snap=transientSnapshot(s,current),plan=planForPresentation(current,snap),resume=view.current&&ensure(s).ui?.resume?.conferenceId===view.current.id&&ensure(s).ui?.resume?.engine===getStageEngine()?.ENGINE_ID&&ensure(s).ui.resume?.planHash===plan.planHash?ensure(s).ui.resume:null,selected=document.getElementById('conferencePlaybackMode')?.value,mode=selected||resume?.mode||'full',scenes=globalThis.GH_CONF_MODEL.scenesForPlan(plan,mode),startScene=resume?Math.max(0,scenes.findIndex(scene=>scene.id===resume.sceneId)):Math.max(0,Math.floor(Number(btn.dataset.slide)||0));launchStage(ctx,current,{live:current.status==='مباشر',startScene,mode});}catch(error){globalThis.GH_WORKFLOW?.notify?.(`تعذر فتح محرك المؤتمر: ${error.message}`,'error',{state:s,panel:'conference'});}return true;}
 if(id==='conference-stage-replay'){try{const view=snapshot(s),year=Math.floor(Number(btn.dataset.year)||0),row=rowForPresentation(s,view,year);launchStage(ctx,row,{live:false,startScene:0,mode:'manual'});}catch(error){globalThis.GH_WORKFLOW?.notify?.(`تعذر إعادة عرض المؤتمر: ${error.message}`,'error',{state:s,panel:'conference'});}return true;}
 if(id==='conference-complete'){try{const out=(await ctx.runAuthorizedDomainCommand('conference','complete',{}, {idempotencyKey:`${ensure(s).current?.id||'CONFERENCE'}-COMPLETE`})).result;ctx.pushAlert(`اختتم مؤتمر ${out.year} وحُفظ كاملًا في الأرشيف.`);ctx.updateKpis();ctx.openDrawer('conference','archive');}catch(error){globalThis.GH_WORKFLOW?.notify?.(`تعذر إنهاء المؤتمر: ${error.message}`,'error',{state:s,panel:'conference'});}return true;}
 if(id==='conference-salary-increase'){const company=document.getElementById('conferenceSalaryCompany')?.value||'group',percent=Number(document.getElementById('conferenceSalaryPct')?.value)||0,year=Math.floor(Number(btn.dataset.year)||currentYear(s));if(percent<.5||percent>25){globalThis.GH_WORKFLOW?.notify?.('اختر زيادة بين 0.5% و25%.','error',{state:s,panel:'conference'});return true;}const ref=`SAL-${year+1}-${company}`,ok=globalThis.GH_WORKFLOW?.confirm?globalThis.GH_WORKFLOW.confirm(`اعتماد زيادة ${percent.toFixed(1)}% على مسير رواتب ${company==='group'?(s.profile?.name||'المجموعة'):formalName(s,company)} ابتداءً من المسير القادم؟`,{state:s,panel:'conference',risk:'financial'}):window.confirm('اعتماد زيادة الرواتب؟');if(!ok)return true;try{const out=(await ctx.runAuthorizedDomainCommand('hr','apply-salary-raise',{company,percent,year:year+1,reference:ref,note:`زيادة رواتب معتمدة من المؤتمر التنفيذي ${year}`},{idempotencyKey:ref})).result;ctx.pushAlert(`اعتمدت زيادة رواتب ${percent.toFixed(1)}% لـ${company==='group'?(s.profile?.name||'المجموعة'):formalName(s,company)}. مؤشر الرواتب الآن ${(out.afterIndex*100).toFixed(1)}%.`);ctx.openDrawer('conference','people');}catch(error){globalThis.GH_WORKFLOW?.notify?.(`تعذر اعتماد الزيادة: ${error.message}`,'error',{state:s,panel:'conference'});}return true;}return false;}
